problems.solutionCode:
#include <stdio.h>

int callbackSum7(int a[], int n) {
    int bestVal = a[0], bestCnt = 0;
    for (int i = 0; i < n; i++) {
        int cnt = 0;
        for (int j = 0; j < n; j++) if (a[i] == a[j]) cnt++;
        if (cnt > bestCnt) { bestCnt = cnt; bestVal = a[i]; }
    }
    return bestVal;
}

