int callbackSum8(int a[], int n, int x) {
    return -1;
}

problems.solutionCode:
#include <stdio.h>

int callbackSum8(int a[], int n, int x) {
    int l = 0, r = n - 1;
    while (l <= r) {
        int m = (l + r) / 2;
        if (a[m] == x) return m;
        if (a[m] < x) l = m + 1;
        else r = m - 1;
    }
    return -1;
}

